import random

def parse(stdin):
    parts = stdin.split()
    if len(parts) != 2:
        raise ValueError('Expected 2 tokens')
    return [int(parts[0]), int(parts[1])]

def render(case):
    return f"{case[0]} {case[1]}"

def valid(case):
    return isinstance(case, list) and len(case) == 2 and all(isinstance(x, int) and -100 <= x <= 100 for x in case)

def solve(stdin):
    a, b = parse(stdin)
    return str(a + b)

def generate(seed, index, mode):
    if mode == 'exhaustive':
        vals = list(range(-5, 6))
        if index >= len(vals) * len(vals):
            return None
        return [vals[index // len(vals)], vals[index % len(vals)]]
    if mode == 'random':
        rng = random.Random(seed + index)
        return [rng.randint(-100, 100), rng.randint(-100, 100)]
    if mode == 'adversarial':
        b = [-100, -1, 0, 1, 100]
        pairs = [[x, y] for x in b for y in b]
        return pairs[index % len(pairs)]
    return None

def shrink(case):
    a, b = case
    cands = [[0, b], [a, 0], [0, 0], [a // 2, b], [a, b // 2], [a // 2, b // 2]]
    res = []
    for c in cands:
        if c != case and valid(c) and c not in res:
            res.append(c)
    return res[:16]

